1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
15	 * region code derived from the owner's postcode (the same derivation the locality shares, see
16	 * {@link OwnerRegion}) and HASH8 is the first 8 upper-case hex characters of SHA-256 over the owner's
17	 * normalized (E.164) telephone concatenated with the last name.
18	 *
19	 * <p>The identity is therefore a stable function of who the owner is, not of how many owners already
20	 * exist — the old per-city sequence number is gone.
21	 *
22	 * <p>Should the computed code collide with an existing owner's {@code customerCode}, it is
23	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
24	 * unique, so distinct owners always end up with distinct customer codes.
25	 */
26	public class AssignCustomerCode {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String region = OwnerRegion.of(owner);
30	        String hash8 = hash8(normalizedTelephone(owner.getTelephone()) + owner.getLastName());
31	        String base = region + "-" + hash8;
32	        owner.setCustomerCode(deduplicate(base, existingCustomerCodes(ownerRepository)));
33	    }
34	
35	    /** The {@code customerCode}s already assigned to other owners in the data store. */
36	    private static Set<String> existingCustomerCodes(OwnerRepository ownerRepository) {
37	        Set<String> codes = new HashSet<>();
38	        for (Owner existing : ownerRepository.findAll()) {
39	            String code = existing.getCustomerCode();
40	            if (code != null) {
41	                codes.add(code);
42	            }
43	        }
44	        return codes;
45	    }
46	
47	    /**
48	     * Returns {@code base} if it is not already taken; otherwise appends {@code -<n>} with the
49	     * smallest {@code n} of 2 or more that makes it unique.
50	     */
51	    private static String deduplicate(String base, Set<String> taken) {
52	        if (!taken.contains(base)) {
53	            return base;
54	        }
55	        for (int n = 2; ; n++) {
56	            String candidate = base + "-" + n;
57	            if (!taken.contains(candidate)) {
58	                return candidate;
59	            }
60	        }
61	    }
62	
63	    /**
64	     * The owner's telephone normalized to E.164 (the same way {@link OwnerIdentityKey} does),
65	     * falling back to the trimmed raw value when it cannot form a valid E.164 number. On the create
66	     * path the telephone was already normalized upstream, so this is idempotent.
67	     */
68	    private static String normalizedTelephone(String raw) {
69	        if (raw == null) {
70	            return "";
71	        }
72	        String normalized = E164Telephone.normalize(raw);
73	        return normalized != null ? normalized : raw.trim();
74	    }
75	
76	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code s}. */
77	    private static String hash8(String s) {
78	        try {
79	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
80	            StringBuilder sb = new StringBuilder();
81	            for (byte b : digest) {
82	                sb.append(String.format("%02X", b));
83	                if (sb.length() >= 8) {
84	                    break;
85	                }
86	            }
87	            return sb.substring(0, 8);
88	        }
89	        catch (NoSuchAlgorithmException ex) {
90	            throw new IllegalStateException("SHA-256 not available", ex);
91	        }
92	    }
93	}
