1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.mapper.OwnerMapper;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Derives an owner's REGION code — the single source of truth now shared by both the region prefix
10	 * of the {@code customerCode} and the owner's locality. The postcode decides first (NSW 2000-2099,
11	 * VIC 3000-3099, QLD 4000-4099); when the postcode is absent or in no known range, the fixed
12	 * city-to-region table ({@link OwnerMapper#CITY_REGION}: Sydney-&gt;NSW, Melbourne-&gt;VIC,
13	 * Brisbane-&gt;QLD) is consulted, falling back to {@code UNKNOWN} for an unlisted city.
14	 */
15	public final class OwnerRegion {
16	
17	    /** Region -> inclusive 4-digit postcode range {low, high}. */
18	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
19	        "NSW", new int[] {2000, 2099},
20	        "VIC", new int[] {3000, 3099},
21	        "QLD", new int[] {4000, 4099});
22	
23	    private OwnerRegion() {
24	    }
25	
26	    /** The owner's region code: postcode range first, then the city table, then {@code UNKNOWN}. */
27	    public static String of(Owner owner) {
28	        String byPostcode = fromPostcode(owner.getPostcode());
29	        if (byPostcode != null) {
30	            return byPostcode;
31	        }
32	        return OwnerMapper.CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
33	    }
34	
35	    /**
36	     * Maps a postcode to its region by range, or {@code null} when the postcode is absent,
37	     * non-numeric or in no known range.
38	     */
39	    private static String fromPostcode(String postcode) {
40	        if (postcode == null || postcode.isBlank()) {
41	            return null;
42	        }
43	        int code;
44	        try {
45	            code = Integer.parseInt(postcode.trim());
46	        }
47	        catch (NumberFormatException ex) {
48	            return null;
49	        }
50	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
51	            int[] range = entry.getValue();
52	            if (code >= range[0] && code <= range[1]) {
53	                return entry.getKey();
54	            }
55	        }
56	        return null;
57	    }
58	}
