1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's {@code identityKey}: the single value all duplicate detection is expressed
12	 * through. It is the SHA-256, rendered as 64 lower-case hex characters, of
13	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} — where the email segment
14	 * is empty when the owner has none. Two owners are the same identity when their whole identityKey is
15	 * equal; because the telephone is part of the key, two people with the same last name (same soundex)
16	 * and postcode but <em>different</em> telephones have different keys and are both allowed — they are
17	 * a soft match, not a hard duplicate.
18	 *
19	 * <p>The telephone is normalized to E.164 (the same way as {@link E164Telephone}) and the email is
20	 * trimmed and lower-cased, so differently-formatted values still produce the same key. The last name
21	 * is reduced to its {@link #soundex(String) Soundex} code, so phonetically-equal surnames share the
22	 * same key segment. The key is computed identically for a not-yet-saved owner (in
23	 * {@link CheckOwnerIdentityUnique}) and for the response, so what a client reads back is exactly what
24	 * collisions are judged on.
25	 */
26	public final class OwnerIdentityKey {
27	
28	    private OwnerIdentityKey() {
29	    }
30	
31	    /** The owner's identity key: the 64-hex SHA-256 of {@code telephone|email|soundex(lastName)}. */
32	    public static String of(Owner owner) {
33	        String raw = normalizeTelephone(owner.getTelephone()) + "|" + normalizeEmail(owner.getEmail())
34	                + "|" + soundex(owner.getLastName());
35	        return sha256Hex(raw);
36	    }
37	
38	    private static String normalizeTelephone(String raw) {
39	        if (raw == null) {
40	            return "";
41	        }
42	        String normalized = E164Telephone.normalize(raw);
43	        return normalized != null ? normalized : raw.trim();
44	    }
45	
46	    private static String normalizeEmail(String email) {
47	        if (email == null) {
48	            return "";
49	        }
50	        String trimmed = email.trim();
51	        return trimmed.isEmpty() ? "" : trimmed.toLowerCase(Locale.ROOT);
52	    }
53	
54	    /** Lower-case hex SHA-256 digest of the given value. */
55	    private static String sha256Hex(String value) {
56	        try {
57	            byte[] digest = MessageDigest.getInstance("SHA-256")
58	                    .digest(value.getBytes(StandardCharsets.UTF_8));
59	            StringBuilder sb = new StringBuilder(digest.length * 2);
60	            for (byte b : digest) {
61	                sb.append(String.format("%02x", b));
62	            }
63	            return sb.toString();
64	        }
65	        catch (NoSuchAlgorithmException e) {
66	            throw new IllegalStateException(e);
67	        }
68	    }
69	
70	    /**
71	     * The American Soundex code of a name: the first letter followed by three digits, so that
72	     * phonetically-similar surnames share a code. A {@code null}, empty, or letter-free value yields
73	     * the empty string.
74	     */
75	    public static String soundex(String value) {
76	        if (value == null) {
77	            return "";
78	        }
79	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
80	        if (letters.isEmpty()) {
81	            return "";
82	        }
83	        StringBuilder code = new StringBuilder();
84	        char first = letters.charAt(0);
85	        code.append(first);
86	        char previous = digit(first);
87	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
88	            char c = letters.charAt(i);
89	            char d = digit(c);
90	            if (d != '0' && d != previous) {
91	                code.append(d);
92	            }
93	            // 'H' and 'W' do not reset the running code (so consonants they separate still merge);
94	            // every other letter, vowels included, does.
95	            if (c != 'H' && c != 'W') {
96	                previous = d;
97	            }
98	        }
99	        while (code.length() < 4) {
100	            code.append('0');
101	        }
102	        return code.toString();
103	    }
104	
105	    /** Soundex digit for a letter; {@code '0'} for vowels and the ignored letters (H, W, Y). */
106	    private static char digit(char c) {
107	        switch (c) {
108	            case 'B': case 'F': case 'P': case 'V':
109	                return '1';
110	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
111	                return '2';
112	            case 'D': case 'T':
113	                return '3';
114	            case 'L':
115	                return '4';
116	            case 'M': case 'N':
117	                return '5';
118	            case 'R':
119	                return '6';
120	            default:
121	                return '0';
122	        }
123	    }
124	}
