1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns every owner a deterministic {@code householdId}: the first 12 hex characters of
12	 * {@code SHA-256(normalizedLastName + '|' + postcode)}. The identifier is a pure function of the
13	 * household's last name and postcode, so two owners with the same last name at the same postcode
14	 * share it automatically — no back-fill and no dependence on {@code sharesHousehold} or the order
15	 * owners were created.
16	 *
17	 * <p>The shared householdId is what every household rule keys off: it forms part of each owner's
18	 * {@link OwnerIdentityKey identityKey}, it is the key the household-duplicate check
19	 * ({@link CheckHouseholdUnique}) matches on, and it is the key the household-size input to the
20	 * membership level ({@link AssignHouseholdMemberCount}) groups by. {@code sharesHousehold} no longer
21	 * creates the link; it only bypasses the duplicate block for a declared household member.
22	 */
23	public class AssignHouseholdId {
24	
25	    public void service(@Val Owner owner) {
26	        owner.setHouseholdId(deriveHouseholdId(normalize(owner.getLastName()), postcode(owner)));
27	    }
28	
29	    /**
30	     * The first 12 hex characters of {@code SHA-256(normalizedLastName + '|' + postcode)} — a stable
31	     * identifier shared by every owner with the same last name and postcode.
32	     */
33	    private static String deriveHouseholdId(String lastName, String postcode) {
34	        try {
35	            byte[] digest = MessageDigest.getInstance("SHA-256")
36	                    .digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
37	            StringBuilder sb = new StringBuilder(12);
38	            for (int i = 0; i < 6; i++) {
39	                sb.append(String.format("%02x", digest[i]));
40	            }
41	            return sb.toString();
42	        }
43	        catch (NoSuchAlgorithmException e) {
44	            throw new IllegalStateException(e);
45	        }
46	    }
47	
48	    /** The postcode as supplied, trimmed; an absent postcode contributes the empty string. */
49	    private static String postcode(Owner owner) {
50	        String postcode = owner.getPostcode();
51	        return postcode == null ? "" : postcode.trim();
52	    }
53	
54	    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
55	    private static String normalize(String value) {
56	        if (value == null) {
57	            return "";
58	        }
59	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
60	    }
61	}
