1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.OwnerIdentityConflictException;
7	
8	/**
9	 * The single, consolidated duplicate check for {@code POST /api/owners}: rejects the request with
10	 * 409 when the new owner's whole {@link OwnerIdentityKey identityKey} (the 64-hex SHA-256 over
11	 * {@code normalizedTelephone|lowerEmail|soundex(lastName)}) equals an existing owner's. This is now
12	 * the only duplicate rule — the former separate telephone, email and household-duplicate checks are
13	 * gone. Because the telephone is part of the key, two people with the same last name (same soundex)
14	 * and postcode but different telephones have different keys and are both allowed — only an exact
15	 * full-key match is a duplicate; the near miss is a soft match (see {@link AssignPossibleDuplicate}).
16	 *
17	 * <p>Soft-deleted owners are ignored, so a new identity is never blocked by one. Runs before
18	 * {@link SaveOwner} so the not-yet-saved owner is not compared against itself. The email-domain
19	 * blocklist has already been applied upstream (in {@link ValidateOwnerFields}).
20	 */
21	public class CheckOwnerIdentityUnique {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
24	            throws OwnerIdentityConflictException {
25	        String identityKey = OwnerIdentityKey.of(owner);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
28	                continue;
29	            }
30	            if (Boolean.TRUE.equals(existing.getDeleted())) {
31	                continue; // a soft-deleted owner no longer blocks a new identity
32	            }
33	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
34	                throw new OwnerIdentityConflictException(
35	                        "An owner with identity " + identityKey + " already exists");
36	            }
37	        }
38	    }
39	}
