3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Emits an audit line on the dedicated {@code AUDIT} logger after a successful create,
15	 * carrying the newly-assigned owner id, its customerCode, its registrationDate, its
16	 * numeric membershipLevel and its membershipNumber. Runs after {@code save}, so the
17	 * owner's generated id is available. The logged level is the household-capped one, so it
18	 * matches what the response and later reads return.
19	 *
20	 * <p>Alongside the human-readable line, emits an immutable structured event on the same
21	 * {@code AUDIT} logger: a JSON object
22	 * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}} where
23	 * {@code seq} is a monotonically increasing integer across creates. The event carries the
24	 * owner's current primary identifier via {@link #primaryIdentifier(Owner)} — the
25	 * customerCode today, and whatever replaces it later.
26	 */
27	public class AuditOwnerCreated {
28	
29	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
30	
31	    /** Monotonically increasing sequence across all creates in this instance. */
32	    private static final AtomicLong SEQ = new AtomicLong();
33	
34	    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository) {
35	        int membershipLevel = HouseholdLevelCap.cappedMembershipLevel(owner, ownerMapper, ownerRepository);
36	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
37	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
38	            membershipLevel, ownerMapper.membershipNumber(owner));
39	
40	        long seq = SEQ.incrementAndGet();
41	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"customerCode\":{},\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
42	            seq, owner.getId(), jsonString(primaryIdentifier(owner)), membershipLevel);
43	    }
44	
45	    /**
46	     * The owner's current primary identifier carried by the structured event. Today that is the
47	     * {@code customerCode}; when the customerCode is later unified into the {@code memberId},
48	     * return that here instead and the event carries the memberId with no other change.
49	     */
50	    private static String primaryIdentifier(Owner owner) {
51	        return owner.getCustomerCode();
52	    }
53	
54	    /** Renders a value as a JSON string literal (quoted, with the minimal escaping), or {@code null}. */
55	    private static String jsonString(String value) {
56	        if (value == null) {
57	            return "null";
58	        }
59	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
60	        for (int i = 0; i < value.length(); i++) {
61	            char c = value.charAt(i);
62	            switch (c) {
63	                case '"' -> sb.append("\\\"");
64	                case '\\' -> sb.append("\\\\");
65	                case '\n' -> sb.append("\\n");
66	                case '\r' -> sb.append("\\r");
67	                case '\t' -> sb.append("\\t");
68	                default -> sb.append(c);
69	            }
70	        }
71	        return sb.append('"').toString();
72	    }
73	}
