15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(\"/api/owners/\" + owner.getId())")
22	    @Mapping(target = "displayName",
23	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
25	    @Mapping(target = "initials",
26	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
30	    @Mapping(target = "identityKey",
31	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.of(owner))")
32	    @Mapping(target = "telephoneDisplay",
33	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.E164Telephone.display(owner.getTelephone()))")
34	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
35	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
36	    @Mapping(target = "locality", expression = "java(locality(owner))")
37	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
38	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
39	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
40	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
41	    OwnerDto toOwnerDto(Owner owner);
42	
43	    /**
44	     * Derives the owner's salutation: the {@code title} and {@code lastName} separated by a single
45	     * space (e.g. {@code "DR Franklin"}), or just the {@code lastName} when no title was supplied.
46	     */
47	    default String salutation(Owner owner) {
