4	 * Normalizes a telephone number to E.164 form:
5	 * <ul>
6	 *   <li>separators (spaces, dashes, brackets and the like) are stripped;</li>
7	 *   <li>a leading {@code '+'} and country code are kept when present;</li>
8	 *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
9	 *       is dropped from the national digits;</li>
10	 *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
11	 *   <li>the national-number length must match the country code: {@code '+61'} requires 9
12	 *       national digits and {@code '+1'} requires 10.</li>
13	 * </ul>
14	 * So {@code "0412 345 678"} becomes {@code "+61412345678"}. Returns {@code null} when the
15	 * input cannot form a valid E.164 number.
16	 *
17	 * <p>{@link #display(String)} does the inverse presentation step: it renders a stored E.164
18	 * number back for humans (country code, space, national digits grouped in threes), e.g.
19	 * {@code "+61412345678"} becomes {@code "+61 412 345 678"}.
20	 */
21	public final class E164Telephone {
22	
23	    private static final int MIN_DIGITS = 8;
24	    private static final int MAX_DIGITS = 15;
25	
26	    /** National-number length required for country code {@code '+61'}. */
27	    private static final int AU_NATIONAL_DIGITS = 9;
28	
29	    /** National-number length required for country code {@code '+1'}. */
30	    private static final int NANP_NATIONAL_DIGITS = 10;
31	
32	    private E164Telephone() {
33	    }
34	
35	    static String normalize(String raw) {
36	        if (raw == null) {
37	            return null;
38	        }
39	        String trimmed = raw.trim();
40	        boolean explicitCountryCode = trimmed.startsWith("+");
41	        String digits = trimmed.replaceAll("\\D", "");
42	        if (!explicitCountryCode) {
43	            if (digits.startsWith("0")) {
44	                digits = digits.substring(1);
45	            }
46	            digits = "61" + digits;
47	        }
48	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
49	            return null;
50	        }
51	        // National-number length must match the country code.
52	        if (digits.startsWith("61")) {
53	            if (digits.length() - 2 != AU_NATIONAL_DIGITS) {
54	                return null;
55	            }
56	        }
57	        else if (digits.startsWith("1")) {
58	            if (digits.length() - 1 != NANP_NATIONAL_DIGITS) {
59	                return null;
60	            }
61	        }
62	        return "+" + digits;
63	    }
64	
65	    /**
66	     * Formats a stored E.164 number for humans: a {@code '+'} and country code, a space, then the
67	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes
68	     * {@code "+61 412 345 678"}). The country code is taken as one digit for the {@code '+1'} NANP
69	     * and two digits otherwise, matching the country codes this app normalizes to. Returns
70	     * {@code null} when the value is absent or not in E.164 (leading {@code '+'}) form.
71	     */
72	    public static String display(String e164) {
73	        if (e164 == null) {
74	            return null;
75	        }
76	        String trimmed = e164.trim();
77	        if (!trimmed.startsWith("+")) {
78	            return null;
79	        }
80	        String digits = trimmed.substring(1).replaceAll("\\D", "");
81	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
82	        if (digits.length() <= countryCodeLength) {
83	            return null;
84	        }
85	        String national = digits.substring(countryCodeLength);
86	        StringBuilder display = new StringBuilder("+").append(digits, 0, countryCodeLength);
87	        for (int i = 0; i < national.length(); i += 3) {
88	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
89	        }
90	        return display.toString();
91	    }
